import React from 'react';

const ProductionTimeline = ({ milestones, tasks }) => {
  // Timeline data
  const phases = [
    { id: 'pre-production', name: 'PRE-PRODUCTION', order: 0, color: '#f7abff' },
    { id: 'production', name: 'PRODUCTION', order: 1, color: '#3CDFFF' },
    { id: 'post-production', name: 'POST-PRODUCTION', order: 2, color: '#a855f7' }
  ];

  // Calculate completion for each milestone
  const calculateMilestoneProgress = () => {
    const progress = {};

    phases.forEach(phase => {
      const milestoneName = phase.name.charAt(0) + phase.name.slice(1).toLowerCase();
      const milestoneTasks = tasks.filter(task => task.milestone === milestoneName);
      const totalTasks = milestoneTasks.length;
      const completedTasks = milestoneTasks.filter(task => task.completed).length;

      progress[phase.id] = totalTasks > 0 ? (completedTasks / totalTasks) * 100 : 0;
    });

    return progress;
  };

  // Determine active phase
  const getActivePhase = () => {
    const activeMilestone = milestones.find(m => m.active);
    if (!activeMilestone) return phases[0].id;

    const milestoneName = activeMilestone.name.toLowerCase().replace('-', '');
    const matchingPhase = phases.find(p => p.id === milestoneName);
    return matchingPhase ? matchingPhase.id : phases[0].id;
  };

  // Calculate timeline position based on completed tasks
  const calculatePosition = () => {
    const progress = calculateMilestoneProgress();
    const activePhase = getActivePhase();
    const activePhaseIndex = phases.findIndex(p => p.id === activePhase);

    // Base position for the start of current phase
    const basePosition = (activePhaseIndex * 100) / phases.length;

    // Progress within the current phase
    const phaseWidth = 100 / phases.length;
    const phaseProgress = (progress[activePhase] * phaseWidth) / 100;

    return basePosition + phaseProgress;
  };

  const currentPosition = calculatePosition();
  const activePhaseId = getActivePhase();

  return (
    <div className="w-full mt-8 mb-12 relative rounded-lg shadow-lg overflow-hidden" style={{ backgroundColor: '#1e1b1e' }}>
      {/* Gradient Background */}
      <div className="absolute inset-0 bg-gradient-to-br from-gray-800 via-gray-900 to-black opacity-70" />

      <div className="relative p-6">
        <h2 className="text-2xl font-bold text-pink-400 mb-4 tracking-wider">Production Timeline</h2>
        <p className="text-gray-400 mb-6">Track your project's progress through major production phases</p>

        {/* Phase Sections with Enhanced Styling */}
        <div className="flex flex-row h-48 rounded-md overflow-hidden border border-gray-700">
          {phases.map((phase, index) => {
            const isActive = phase.id === activePhaseId;
            const progress = calculateMilestoneProgress()[phase.id] || 0;
            const isFirst = index === 0;
            const isLast = index === phases.length - 1;

            return (
              <div
                key={phase.id}
                className={`flex-1 flex flex-col justify-center items-center relative transition-all duration-300 ease-in-out ${isActive ? 'bg-purple-900 bg-opacity-50' : 'bg-gray-800 bg-opacity-30 hover:bg-gray-700 bg-blend-overlay'}`}
                style={{ borderRight: !isLast ? '1px solid #333' : 'none' }}
              >
                <div className="absolute top-4 left-4 text-lg font-semibold text-white opacity-80">{phase.name}</div>
                <div className="text-white text-xl font-bold mt-6">{Math.round(progress)}%</div>
                <div className="text-gray-400 text-sm">Complete</div>

                {/* Subtle Progress Bar inside each phase */}
                <div className="absolute bottom-0 left-0 w-full h-1 bg-gradient-to-r from-pink-400 to-purple-600 opacity-60" style={{ width: `${progress}%` }} />
              </div>
            );
          })}
        </div>

        {/* Timeline Bar with Glow Effect */}
        <div className="relative mt-8">
          <div className="w-full h-2 bg-gray-700 rounded-full overflow-hidden">
            <div
              className="h-full bg-gradient-to-r from-pink-500 to-purple-500 rounded-full shadow-md"
              style={{ width: `${currentPosition}%` }}
            />
          </div>
          {/* "You are here" indicator with pulse */}
          <div
            className="absolute -bottom-3 flex flex-col items-center transition-all duration-300 ease-out"
            style={{
              left: `${currentPosition}%`,
              transform: 'translateX(-50%)'
            }}
          >
            <div className="text-white text-sm font-semibold mb-1 animate-pulse">YOU ARE HERE</div>
            <div className="w-3 h-3 rounded-full bg-pink-500 shadow-lg" />
            <div className="h-6 w-px bg-gray-500" />
          </div>
        </div>
      </div>
    </div>
  );
};

export default ProductionTimeline;
